files.content:
* { box-sizing: border-box; }
:root {
  color-scheme: dark;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 16px;
  background: #172326;
  color: #f2f1df;
  --ink: #172326;
  --panel: #223236;
  --line: #405357;
  --lime: #c5ef70;
  --muted: #a8b8b2;
}
body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #172326;
  background-image: linear-gradient(#243438 1px, transparent 1px), linear-gradient(90deg, #243438 1px, transparent 1px);
  background-size: 24px 24px;
}
.card {
  width: min(100%, 520px);
  padding: clamp(24px, 6vw, 40px);
  border: 1px solid #526567;
  border-radius: 8px;
  background: var(--panel);
  box-shadow: 8px 8px 0 #10191b;
}
.pixel-mark { display: flex; gap: 5px; margin-bottom: 22px; }
.pixel-mark span { width: 10px; height: 10px; background: var(--lime); }
.pixel-mark span:nth-child(2) { opacity: .75; }
.pixel-mark span:nth-child(3) { opacity: .5; }
.pixel-mark span:nth-child(4) { opacity: .25; }
.eyebrow { margin: 0 0 8px; color: var(--lime); font-size: .8rem; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.8rem); letter-spacing: -.06em; }
.intro { margin: 10px 0 30px; color: var(--muted); line-height: 1.5; }
label { display: block; margin: 18px 0 9px; font-weight: 700; }
.range-note { float: right; color: var(--muted); font-size: .85rem; font-weight: 400; }
textarea, input, .result {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--ink);
  color: #f2f1df;
  font: inherit;
}
textarea { min-height: 128px; padding: 14px; resize: vertical; line-height: 1.55; }
textarea::placeholder { color: #81928c; }
input { height: 48px; padding: 0 14px; }
textarea:focus-visible, input:focus-visible, button:focus-visible, .result:focus-visible { outline: 3px solid var(--lime); outline-offset: 3px; }
.actions { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 20px 0 26px; }
button { min-height: 48px; padding: 10px 14px; border: 1px solid var(--lime); border-radius: 5px; background: var(--lime); color: var(--ink); font: inherit; font-weight: 700; cursor: pointer; transition: transform .12s ease, background-color .12s ease, box-shadow .12s ease; }
button:hover { background: #d7f69b; box-shadow: 0 3px 0 #8eb543; transform: translateY(-1px); }
button:active { transform: translateY(1px); box-shadow: none; }
button.secondary { border-color: #82918d; background: transparent; color: #f2f1df; }
button.secondary:hover { background: #34474a; box-shadow: 0 3px 0 #10191b; }
.result-heading { display: flex; align-items: center; justify-content: space-between; }
.result-heading label { margin: 0 0 9px; }
.copy-button { min-height: 32px; padding: 4px 10px; border-color: var(--line); background: transparent; color: var(--muted); font-size: .85rem; }
.copy-button:hover { border-color: var(--lime); background: #34474a; color: #f2f1df; box-shadow: none; }
.result { min-height: 82px; padding: 14px; overflow-wrap: anywhere; white-space: pre-wrap; line-height: 1.55; }
.result:empty::before { content: 'Your transformed message will appear here.'; color: #81928c; }
.feedback { min-height: 1.3em; margin: 8px 0 0; color: var(--lime); font-size: .85rem; }
.hint { margin: 16px 0 0; color: var(--muted); font-size: .85rem; line-height: 1.5; }
@media (max-width: 400px) { .card { padding: 22px 18px; } .actions { gap: 8px; } button { padding-inline: 9px; } }

const messageInput = document.getElementById('message');
const shiftInput = document.getElementById('shift');
const result = document.getElementById('result');
const feedback = document.getElementById('feedback');

function transform(text, amount) {
  return [...text].map((character) => {
    const code = character.charCodeAt(0);
    const base = code >= 65 && code <= 90 ? 65 : code >= 97 && code <= 122 ? 97 : -1;
    return base < 0 ? character : String.fromCharCode(((code - base + amount) % 26 + 26) % 26 + base);
  }).join('');
}

function run(direction) {
  const shift = Number(shiftInput.value);
  if (!Number.isInteger(shift) || shift < 1 || shift > 25) {
    shiftInput.setAttribute('aria-invalid', 'true');
    feedback.textContent = 'Enter a whole number from 1 to 25.';
    shiftInput.focus();
    return;
  }
  shiftInput.removeAttribute('aria-invalid');
  feedback.textContent = '';
  result.textContent = transform(messageInput.value, direction * shift);
}

document.getElementById('encode').addEventListener('click', () => run(1));
document.getElementById('decode').addEventListener('click', () => run(-1));
shiftInput.addEventListener('input', () => {
  shiftInput.removeAttribute('aria-invalid');
  feedback.textContent = '';
});
document.getElementById('copy').addEventListener('click', async () => {
  if (!result.textContent || result.textContent === 'Your transformed message will appear here.') {
    feedback.textContent = 'Encode or decode a message first.';
    return;
  }
  try {
    await navigator.clipboard.writeText(result.textContent);
    feedback.textContent = 'Result copied.';
  } catch {
    feedback.textContent = 'Copy is unavailable here. Select the result and copy it manually.';
  }
});
